inline void enc_holder(std::string& out, const Holder& v, int depth) {
    if (wire_name(v.evidence).empty()) throw Refusal("bad_enum", 0);
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "program");
    out += ": ";
    esc(out, v.program);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "account");
    out += ": ";
    esc(out, v.account);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "amount");
    out += ": ";
    num(out, v.amount);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "evidence");
    out += ": ";
    esc(out, std::string(wire_name(v.evidence)));
    if (!v.lease.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "lease");
        out += ": ";
        esc(out, v.lease);
    }
    if (!v.grant.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "grant");
        out += ": ";
        esc(out, v.grant);
    }
    if (!v.since.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "since");
        out += ": ";
        esc(out, write_timestamp(v.since));
    }
    if (!v.detail.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "detail");
        out += ": ";
        esc(out, v.detail);
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

